(function(s){"use strict";var e=function(){if(country===""&&institute===""&&searchQuery===""){return}var e=s("#view-submission-preloader").clone();e.attr("id","searchPageThrobber");s("#user-list").html(e);s.ajax({url:searchURL,method:"GET",data:{country:country,institute:institute,q:searchQuery},success:function(e){s("#user-list").html(e["table"])},error:function(e){s.web2py.flash("Error retrieving users");console.log(e)}})};s(document).ready(function(){e();s("#searchUserForm").submit(function(){if(s("#searchInput").val()===""&&s("#institute option:selected").val()===""&&s("#country option:selected").val()===""){s.web2py.flash("Please add search filters");return false}});s(document).on("click","button",function(){var e=s(this),t=e.attr("data-userid"),a=e.attr("data-buttontype"),r=s(e.children()[0]);if(a=="add-friend"){e.addClass("black");e.removeClass("green");e.attr("data-buttontype","unfriend");e.attr("data-tooltip","Unfriend");r.removeClass("fa-user-plus");r.addClass("fa-user-times");s.ajax({method:"POST",url:"/default/mark_friend/"+t}).done(function(e){s.web2py.flash(e)})}else if(a=="unfriend"){e.removeClass("black");e.addClass("green");e.attr("data-buttontype","add-friend");e.attr("data-tooltip","Add friend");r.removeClass("fa-user-times");r.addClass("fa-user-plus");s.ajax({method:"POST",url:"/default/unfriend/"+t}).done(function(e){s.web2py.flash(e)})}})})})(jQuery);